import{_ as t,l as d,o as a,c as o,v as r,p,x as i,d as c,i as l,S as n}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"device mapper 与 LVM","description":"","frontmatter":{"title":"device mapper 与 LVM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/device-mapper-lvm.md","filePath":"cs/device-mapper-lvm.md","lastUpdated":1789023840000}'),m={name:"cs/device-mapper-lvm.md"};function h(V,e,v,f,_,u){const s=d("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="device-mapper-与-lvm" tabindex="-1">device mapper 与 LVM <a class="header-anchor" href="#device-mapper-与-lvm" aria-label="Permalink to &quot;device mapper 与 LVM&quot;">​</a></h1><div class="epigraph"><p>device mapper 把「逻辑块号」翻译成一个或多个底层设备上的段；LVM 用 PV/VG/LV 把这套映射做成可管理的卷。</p><footer>—— 据 Linux device-mapper 文档；LVM2 设计说明；McKusick 对卷管理的背景</footer></div><p><a href="/cs/scsi-stack">上一课</a>交出 <code>/dev/sd*</code>。<a href="/cs/ext2-block-groups">文件系统</a> 以为自己拥有整盘。生产上要在线扩容、快照、加密——不必新做一种 FS。缺口是 <strong>dm</strong>：内核映射表；LVM 是用户态的表生成器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一张表：逻辑区间 → (磁盘, 偏移, 类型)。linear 拼接；striped 条带；snapshot 写时复制块设备（与 <a href="/cs/fs-snapshots">btrfs 快照</a> 不同层）；thin 后课再讲。ioctl/<code>dmsetup</code> 装表，出现 <code>/dev/dm-N</code>。LVM：物理卷打标签，卷组凑空间，逻辑卷 = 一段表。缺口：挂载的是 LV 节点；扩容是改表加 FS <code>resize</code>；与 <a href="/cs/device-nodes">设备节点</a> 的关系。</p><p><span class="marginnote">表可热替换（reload），有短暂冻结 I/O。镜像与 RAID 可走 dm 或后课 md。本课不把每一个 target 写成清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读 LV 偏移 x：查表得底层 y，把 bio remap 下去。写 snapshot：第一次写某块时拷旧到 COW 区再写。对照 FS COW：这里粒度是设备块，文件系统不知情。对照 <a href="/cs/nvme-driver">NVMe</a>：dm 仍在块层之上，每 I/O 多一次映射。</p>',8)),(a(),p(n,null,{default:i(()=>[l(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20LV%5B%22dm%20%E9%80%BB%E8%BE%91%E8%AE%BE%E5%A4%87%22%5D%0A%20%20LV%20--%3E%20T%5B%22%E6%98%A0%E5%B0%84%E8%A1%A8%22%5D%0A%20%20T%20--%3E%20PV%5B%22PV%20%E6%88%96%E5%88%86%E5%8C%BA%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>dm 把存储虚拟化放进内核块层，使策略（扩容、加密、多路径）可组合：表可以叠（LV 上再 crypt）。LVM 只是把表存进元数据并在启动时恢复。不要把 LVM 快照当成 btrfs send 的替代叙述——粒度与一致性范围不同：设备快照不知道 FS 事务。</p><p>与 <a href="/cs/fsync">fsync</a>：flush 要传到底层；表不能吞掉屏障，后课 FUA 再钉。</p><p>实现上：表 reload 时内核冻结目标，正在飞的 bio 要排完或重映射。LVM 元数据存在 PV 开头，损坏则 VG 消失，和 FS 超级块是两套备份故事。 读法上只引用<a href="/cs/scsi-stack">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>device mapper 与 LVM</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入集群 LVM、lvmlockd。不保证精简池的丢弃行为——<a href="/cs/thin-provisioning">精简配置</a> 专课。下一课另一条做 RAID 的内核路径：md。</p><p>版本字段会变，课序钉的是机制对象「device mapper 与 LVM」，不是某一主线内核的结构体名。 后课默认：逻辑卷是块层映射表。软 RAID 如何把多盘收成一个 md 设备，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>dm 用映射表 remap bio；LVM 管理 PV/VG/LV。</li><li>设备级快照不是文件系统快照。</li><li>md RAID 是下一课。</li><li>出处：Linux DM；LVM2；<em>OSTEP</em> 对 RAID/卷的背景。</li></ul>',11))])}const M=t(m,[["render",h]]);export{E as __pageData,M as default};
